def install_apk(self, apk_path: str | Path):
    """Install an APK file on an Android device.

    :param apk_path: The path of the Android APK file to install.
    :returns: `None` on success; raises an exception on failure.
    """
    try:
        self.run("install", "-r", apk_path)
    except subprocess.CalledProcessError as e:
        # Show any output from the failing subprocess to aid troubleshooting.
        # Subprocess.check_output usually places combined stdout/stderr into e.output;
        # be defensive and also check e.stderr, and decode bytes if necessary.
        parts: list[str] = []
        for attr in ("output", "stderr"):
            val = getattr(e, attr, None)
            if val:
                if isinstance(val, bytes):
                    try:
                        val = val.decode(errors="replace")
                    except Exception:
                        val = str(val)
                parts.append(str(val))

        failing_output = "\n".join(p for p in parts if p).strip()
        if failing_output:
            self.tools.console.error("adb output from failed install:")
            for line in failing_output.splitlines():
                self.tools.console.error(f"    {line}")

        raise BriefcaseCommandError(
            f"Unable to install APK {apk_path} on {self.device}"
        ) from e
